    Bug 1902742 - Prevent display names from ISPDB mistakenly being parsed as a date. r=babolivier

    Differential Revision: https://phabricator.services.mozilla.com/D220373

diff --git a/mailnews/base/src/JXON.sys.mjs b/mailnews/base/src/JXON.sys.mjs
index 8704960f916..7e3a6e02635 100644
--- a/mailnews/base/src/JXON.sys.mjs
+++ b/mailnews/base/src/JXON.sys.mjs
@@ -11,18 +11,14 @@ export var JXON = new (function () {
   const sElementListPrefix = "$";
   const sConflictSuffix = "_"; // used when there's a name conflict with special JXON properties
   const aCache = [];
-  const rIsBool = /^(?:true|false)$/i;

   function parseText(sValue) {
-    if (rIsBool.test(sValue)) {
+    if (/^(?:true|false)$/i.test(sValue)) {
       return sValue.toLowerCase() === "true";
     }
     if (isFinite(sValue)) {
       return parseFloat(sValue);
     }
-    if (isFinite(Date.parse(sValue))) {
-      return new Date(sValue);
-    }
     return sValue;
   }
